                Vector3 forward=Vector3.ProjectOnPlane(rig.Head.transform.forward,Vector3.up).normalized;if(forward.sqrMagnitude<.5f)forward=Vector3.forward;Vector3 across=Vector3.Cross(Vector3.up,forward);Quaternion model=Quaternion.LookRotation(forward,Vector3.up),raw=model*Quaternion.Inverse(R23TrackedGripPose.LocalRotation);
